func writeSkills(tx *gorm.DB, values map[uint16]assets.Skill) error {
	var rows []SkillsRow
	for key, value := range values {
		row := SkillsRow{SkillsKey: key}
		row.ValueEffectRefsPresent = value.EffectRefs != nil
		row.ValueNativePattern109 = value.NativePattern109
		row.ValueNativePattern110 = value.NativePattern110
		row.ValueNativePattern111 = value.NativePattern111
		row.ValueNativePattern112 = value.NativePattern112
		if value.AreaAttack != nil {
			row.ValueAreaAttackPresent = true
			row.ValueAreaAttack = (*value.AreaAttack)
		}
		row.ValueNativeRounds51 = value.NativeRounds51
		row.ValueNativeEffectCode52 = value.NativeEffectCode52
		row.ValueEffectsPresent = value.Effects != nil
		row.ValueID = value.ID
		row.ValueName = value.Name
		row.ValueType = value.Type
		row.ValueSP = value.SP
		row.ValueElement = value.Element
		row.ValueAttack = value.Attack
		row.ValueEffectLayer = value.EffectLayer
		row.ValuePowerPerLevel = value.PowerPerLevel
		row.ValueStatMultiplier = value.StatMultiplier
		row.ValueAdditionalDamage = value.AdditionalDamage
		row.ValueTableOrder = value.TableOrder
		rows = append(rows, row)
	}
	if len(rows) > 0 {
		if err := tx.CreateInBatches(&rows, catalogWriteBatch).Error; err != nil {
			return err
		}
	}
	for key, value := range values {
		if err := writeSkillsEffectRefs(tx, value.EffectRefs, key); err != nil {
			return err
		}
		if err := writeSkillsEffects(tx, value.Effects, key); err != nil {
			return err
		}
	}
	return nil
}
func readSkills(tx *gorm.DB) (map[uint16]assets.Skill, error) {
	result := make(map[uint16]assets.Skill)
	var rows []SkillsRow
	query := tx
	if err := query.Order("skills_key").Find(&rows).Error; err != nil {
		return result, err
	}
	for _, row := range rows {
		var value assets.Skill
		if row.ValueEffectRefsPresent {
			var err error
			value.EffectRefs, err = readSkillsEffectRefs(tx, row.SkillsKey)
			if err != nil {
				return result, err
			}
		}
		value.NativePattern109 = row.ValueNativePattern109
		value.NativePattern110 = row.ValueNativePattern110
		value.NativePattern111 = row.ValueNativePattern111
		value.NativePattern112 = row.ValueNativePattern112
		if row.ValueAreaAttackPresent {
			value.AreaAttack = new(bool)
			(*value.AreaAttack) = row.ValueAreaAttack
		}
		value.NativeRounds51 = row.ValueNativeRounds51
		value.NativeEffectCode52 = row.ValueNativeEffectCode52
		if row.ValueEffectsPresent {
			var err error
			value.Effects, err = readSkillsEffects(tx, row.SkillsKey)
			if err != nil {
				return result, err
			}
		}
		value.ID = row.ValueID
		value.Name = row.ValueName
		value.Type = row.ValueType
		value.SP = row.ValueSP
		value.Element = row.ValueElement
		value.Attack = row.ValueAttack
		value.EffectLayer = row.ValueEffectLayer
		value.PowerPerLevel = row.ValuePowerPerLevel
		value.StatMultiplier = row.ValueStatMultiplier
		value.AdditionalDamage = row.ValueAdditionalDamage
		value.TableOrder = row.ValueTableOrder
		result[row.SkillsKey] = value
	}
	return result, nil
}

